head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.procJob = "";             // 진행 중인 처리명 (완료·실패 메시지 인자) — 원본 procJob
scwin.TAB_PROC = 0;             // [마감처리] 탭
scwin.TAB_HIST = 1;             // [마감처리내역] 탭
scwin.USR_TP_OPERATOR = "1";    // 사용자구분 — 운영자(재마감처리 가능)
scwin.CLOSING_TP_CLS = 1;       // 마감 구분코드 — 마감
scwin.CLOSING_TP_RECLS = 2;     // 마감 구분코드 — 재마감

// 원본 : /pf/ULDSTF09330.gfm (상장형수익증권 마감처리) — gfm 은 저장소에 없고, W-Craft 1차 변환에 API 적용까지 마친 개발 사본으로 분석했다.
/*
 * 화면 동작
 *  - [마감처리] 탭: 마감일(당일 고정)의 다음 영업 상장일에 상장하는 상장형 수익증권 신규상장 목록을 보여 주고 [마감처리]로 마감한다.
 *    운영자(사용자구분 1)는 [재마감처리]를 할 수 있다. 이미 마감됐으면(마감처리시각 있음) [마감처리]는 잠긴다.
 *  - [마감처리내역] 탭: 고른 마감일의 송신목록(마감처리내역)을 조회한다.
 *  - 조회 순서는 원본대로 다음 영업 상장일 → 마감상태 → 탭별 목록.
 *  - 통신·데이터 정의는 개발 사본에 적용된 /api/listing/lstproc/pf/new-listing-closing/ API 5종 기준(명세로 간주).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09330/ULDSTF09330.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 세션 정보 → init 바인딩 → 버튼 초기 상태 → [마감처리] 탭 상태(마감일 = 오늘) → 조회. (원본 scwin.init — §3)
 * 탭 본문은 alwaysDraw="true" 라 처음부터 그려져 있어 탭 안 버튼도 여기서 제어한다(규칙 45 예외, 선례 ULDSTF08200·70016).
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 세션 — 원본 pUsrTpCd
    scwin.usrTpCd = $c.session.getUserInfo("usrTpCd") ?? "";

    // 2) init 바인딩 (전환 규칙 22·37) — 마감일·상장일 단일 달력, 조회 영역 Enter 키
    $c.date.checkCalendarFormat(edt_TASK_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 버튼 초기 상태 — [마감처리]는 마감상태 조회 뒤 정하고(그 전까지 잠금), [재마감처리]는 운영자만 보인다
    btn_TrSend.setDisabled(true);
    scwin.applyReTrSendButton();

    // 4) [마감처리] 탭 상태 — 마감일 = 오늘, 입력 잠금 (원본 setObjectValue(edt_TASK_DD, 오늘) + 탭 0 잠금)
    scwin.applyTabMode(scwin.TAB_PROC);

    // 5) 조회 (원본 fn_list_sync)
    await scwin.listSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.MaxTab_01_onchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 변경 — 탭에 맞춰 마감일 입력 상태를 바꾸고 다시 조회한다. (원본 MaxTab_01_ontabclick — §4, §6.2)
 * @param {String} tabId 선택한 탭 id
 * @param {Number} index 선택한 탭 순번
 * @returns
 * @hidden N
 */
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        scwin.applyTabMode(Number(MaxTab_01.getSelectedTabIndex()));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.MaxTab_01_onchange" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭(조회 영역 Enter 키 포함) — 선택한 탭 기준으로 다시 조회한다. (원본 btn_Search_onclick → fn_list_sync — §5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_TrSend_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리] 클릭. (원본 btn_TrSend_onclick → fn_trsend — §6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_TrSend_onclick = async function (e) {
    try {
        await scwin.closing(scwin.CLOSING_TP_CLS);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.btn_TrSend_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ReTrSend_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [재마감처리] 클릭. (원본 btn_ReTrSend_onclick → fn_re_trsend — §6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ReTrSend_onclick = async function (e) {
    try {
        await scwin.closing(scwin.CLOSING_TP_RECLS);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.btn_ReTrSend_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ProcExcel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리] 탭 엑셀다운로드 클릭. (원본 btn_ProcExcel_onclick → fn_ExcelDown — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ProcExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.btn_ProcExcel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_SearchExcel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리내역] 탭 엑셀다운로드 클릭. (원본 btn_SearchExcel_onclick → fn_ExcelDown — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_SearchExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.btn_SearchExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectNextBzDay
 * @author Inswave
 * @date 2026. 10. 30
 * @description 다음 영업 상장일 조회 — 응답 listDd 를 상장일에 옮긴다. 실패하면 상장일을 비운다. (원본 nextBzSearch — §5.1)
 * @param {String} taskDd 마감일(yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.selectNextBzDay = async function (taskDd) {
    dma_search.set("listDd", "");

    const sbmOptions = {
        id : "sbm_nextBzDay",
        action : "/api/listing/lstproc/pf/new-listing-closing/next-bz-day",
        method : "get",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    if (!result?.responseJSON?.success) return;

    dma_search.set("listDd", result.responseJSON.body?.listDd ?? "");
};

/**
 * @method
 * @name scwin.selectClosingStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감상태(마감자·마감처리시각·파일전송 시작/종료) 조회. (원본 closingSttsSearch — §5.2)
 * @param {String} taskDd 마감일(yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.selectClosingStatus = async function (taskDd) {
    dma_item.setEmptyValue();

    const sbmOptions = {
        id : "sbm_closingStatus",
        action : "/api/listing/lstproc/pf/new-listing-closing/closing-status",
        method : "get",
        target : "dma_item=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리] 탭 목록 — 상장일에 상장하는 신규상장 종목. 조회 뒤 건수와 [마감처리] 버튼 상태를 정한다. (원본 fn_list_sync 탭 0 — §5.3)
 * @param {String} listDd 상장일(yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.selectList = async function (listDd) {
    dlt_list.removeAll();

    const sbmOptions = {
        id : "sbm_list",
        action : "/api/listing/lstproc/pf/new-listing-closing/select-list",
        method : "get",
        target : "dlt_list=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions, { listDd : listDd });
    $c.stf.fillGridHeaderTotalCnt(dlt_list.getRowCount(), edt_New_Proc_TotalCnt);
    scwin.applyTrSendButton();
};

/**
 * @method
 * @name scwin.selectHist
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리내역] 탭 목록 — 고른 마감일의 송신목록. (원본 fn_list_sync 탭 1 — §5.4)
 * @param {String} taskDd 마감일(yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.selectHist = async function (taskDd) {
    dlt_list2.removeAll();

    const sbmOptions = {
        id : "sbm_listHist",
        action : "/api/listing/lstproc/pf/new-listing-closing/select-list-hist",
        method : "get",
        target : "dlt_list2=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    $c.stf.fillGridHeaderTotalCnt(dlt_list2.getRowCount(), edt_New_Search_TotalCnt);
};

/**
 * @method
 * @name scwin.closingProcess
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감·재마감 처리 요청. 성공이면 완료 안내 후 다시 조회한다. (원본 fn_trsend·fn_re_trsend 의 closing-procsss 호출 — §5.5)
 * @param {Number} closingTpCd 마감 구분코드 (1 마감, 2 재마감)
 * @returns
 * @hidden N
 */
scwin.closingProcess = async function (closingTpCd) {
    const requestData = {
        taskDd : dma_search.get("taskDd"),     // 마감일
        listDd : dma_search.get("listDd"),     // 상장일
        closingTpCd : closingTpCd              // 마감·재마감 구분코드
    };

    const sbmOptions = {
        id : "sbm_closingProcess",
        action : "/api/listing/lstproc/pf/new-listing-closing/closing-procsss",
        method : "post",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀 (원본 연속 클릭)

    // TODO: 응답 정의가 없어 성공은 success 로만 판정한다 — 업무 결과 코드가 있는지 확인 (§10 #2)
    if (!result?.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0058"));
    await scwin.listSync();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 다음 영업 상장일 → 마감상태 → 선택한 탭의 목록 순으로 차례로 조회한다. (원본 fn_list_sync — §5)
 * @returns
 * @hidden N
 */
scwin.listSync = async function () {
    if (!await scwin.validateSearch()) return;

    const taskDd = dma_search.get("taskDd");
    await scwin.selectNextBzDay(taskDd);
    await scwin.selectClosingStatus(taskDd);

    if (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_HIST) {
        await scwin.selectHist(taskDd);
    } else {
        await scwin.selectList(dma_search.get("listDd"));
    }
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 전 마감일 확인 — 비었거나 8자리가 아니면 안내한다([마감처리내역] 탭은 마감일을 직접 입력한다). (§6.1)
 * @returns {Boolean} 조회 가능하면 true
 * @hidden N
 */
scwin.validateSearch = async function () {
    const taskDd = String(dma_search.get("taskDd") ?? "");
    if (taskDd.length !== 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_TASK_DD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.applyTabMode
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 상태 — [마감처리] 탭은 마감일을 오늘로 되돌리고 잠그며, [마감처리내역] 탭은 마감일을 입력할 수 있게 연다. (원본 init·MaxTab_01_ontabclick — §6.2)
 * @param {Number} index 탭 순번
 * @returns
 * @hidden N
 */
scwin.applyTabMode = function (index) {
    if (index === scwin.TAB_HIST) {
        edt_TASK_DD.setDisabled(false);
        return;
    }
    dma_search.set("taskDd", $c.date.getServerDateTime("yyyyMMdd"));
    edt_TASK_DD.setDisabled(true);
};

/**
 * @method
 * @name scwin.applyTrSendButton
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리] 버튼 — 마감처리시각이 없을 때(아직 마감 전)만 연다. (원본 buttonTrSend 마감 부분 — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyTrSendButton = function () {
    btn_TrSend.setDisabled(!$c.util.isEmpty(dma_item.get("bzClsTm")));
};

/**
 * @method
 * @name scwin.applyReTrSendButton
 * @author Inswave
 * @date 2026. 10. 30
 * @description [재마감처리] 버튼 — 운영자(사용자구분 1)만 보이고 쓸 수 있다. (원본 buttonTrSend 재마감 부분 — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyReTrSendButton = function () {
    if (scwin.usrTpCd === scwin.USR_TP_OPERATOR) {
        btn_ReTrSend.setDisabled(false);
        btn_ReTrSend.show("");
    } else {
        btn_ReTrSend.setDisabled(true);
        btn_ReTrSend.hide();
    }
};

/**
 * @method
 * @name scwin.closing
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감·재마감 — 상장일이 있는지 확인하고, 확인창에서 예를 고르면 처리한다. (원본 fn_trsend·fn_re_trsend — §6.4)
 * @param {Number} closingTpCd 마감 구분코드 (1 마감, 2 재마감)
 * @returns
 * @hidden N
 */
scwin.closing = async function (closingTpCd) {
    const isRecls = (closingTpCd === scwin.CLOSING_TP_RECLS);
    scwin.procJob = isRecls ? "재마감처리" : "마감처리";

    if ($c.util.isEmpty(dma_search.get("listDd"))) {
        await $c.win.alert("[상장일]이 없습니다.");
        return;
    }

    const msg = isRecls ? "[재마감] 처리 하겠습니까?" : "[마감] 처리 하겠습니까?";
    if (!await $c.win.confirm(msg)) return;

    await scwin.closingProcess(closingTpCd);
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 선택한 탭의 그리드를 내려받는다. 0건 안내는 공통 함수가 한다.
 * 파일명은 {menuId}_{원본 이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42). (원본 fn_ExcelDown — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    const prefix = $c.win.getProgramId() + "_";
    const suffix = "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx";

    if (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_HIST) {
        $c.data.downloadGridViewExcel(grd_New_Search, { fileName : prefix + "상장형 수익증권 신규상장 송신목록" + suffix, sheetName : "리스트" });
    } else {
        $c.data.downloadGridViewExcel(grd_New_Proc, { fileName : prefix + "상장형 수익증권 신규상장 마감처리목록" + suffix, sheetName : "리스트" });
    }
};
